## 中间件顺序和安全配置

```javascript
// 危险配置 - 中间件顺序错误
const app = new Koa();

app.use(router.routes());        // ❌ 路由在安全中间件之前
app.use(helmet());                // ❌ 太晚了

// 正确顺序
const app = new Koa();

// 1. 错误处理 (最外层)
app.use(async (ctx, next) => {
    try {
        await next();
    } catch (err) {
        ctx.status = err.status || 500;
        ctx.body = { error: 'Internal Server Error' };  // ✓ 不泄露详情
        ctx.app.emit('error', err, ctx);
    }
});

// 2. 安全头
app.use(helmet());  // ✓

// 3. CORS
app.use(cors({
    origin: 'https://app.example.com',  // ✓ 具体域名
    credentials: true
}));

// 4. 请求体解析
app.use(bodyParser({
    jsonLimit: '1mb',  // ✓ 限制大小
    formLimit: '1mb'
}));

// 5. 身份验证
app.use(auth());

// 6. 路由 (最后)
app.use(router.routes());
app.use(router.allowedMethods());
```

