    return Limit::perMinute(5)->by($request->input('email'));  // ✓ 按邮箱限制
});

Route::post('/login', [AuthController::class, 'login'])
    ->middleware('throttle:login');

// 3. 使用验证码
// 登录失败3次后要求验证码
