## 检测命令

```bash
# 搜索所有 unserialize 调用
grep -rn "unserialize\s*(" --include="*.php" .

# 检查用户输入来源
grep -rn "unserialize.*\$_" --include="*.php" .
grep -rn "unserialize.*\$_COOKIE\|unserialize.*\$req" --include="*.php" .

# 搜索危险魔术方法
grep -rn "function\s*__destruct\|function\s*__wakeup\|function\s*__toString" --include="*.php" .

# 搜索 Phar 相关
grep -rn "phar://\|new Phar\|setMetadata" --include="*.php" .
grep -rn "file_exists\|file_get_contents" --include="*.php" . | grep "\$"

# 搜索动态调用
grep -rn "call_user_func\|call_user_func_array\|\$[a-zA-Z_]+\s*\(" --include="*.php" .

# 使用 PHPGGC 分析框架
./phpggc -l | grep -i "laravel\|thinkphp\|yii\|symfony"
./phpggc Laravel/RCE1 system id
```

